begin;
set local statement_timeout='20s';
select pg_advisory_xact_lock(1617125,13);
create temporary table batch_input as select * from jsonb_to_recordset($data$[{"shop": "PearlsTreasuresArt", "handle": "cindyzhang62", "listing_id": "1895005417", "source_url": "https://www.etsy.com/listing/1895005417/natural-seashell-earrings-baroque-pearl", "category": "Seashell Jewelry", "board_id": "675399344058025061", "new_title": "Shell and Baroque Pearl Drop Earrings", "body": "Shell details and baroque pearl drops bring an ocean-inspired accent to an outfit. PearlsTreasuresArt offers stud and clip options; choose the fitting you need in the original listing.", "image_url": "https://i.etsystatic.com/46725934/r/il/46c7cc/6807649625/il_794xN.6807649625_30o7.jpg", "facebook_draft": "Shell details with a pearl drop: explore the stud and clip options from PearlsTreasuresArt. https://www.etsy.com/listing/1895005417/natural-seashell-earrings-baroque-pearl", "checked_at": "2026-10-19T02:39:03.068706+00:00", "visual_verified": true, "available": true}, {"shop": "PearlsTreasuresArt", "handle": "cindyzhang62", "listing_id": "1899462379", "source_url": "https://www.etsy.com/listing/1899462379/handmade-seashell-drop-earrings-boho", "category": "Seashell Jewelry", "board_id": "675399344058025061", "new_title": "Shell Drop Earrings for Coastal Outfits", "body": "A spiral shell silhouette creates a coastal statement. Explore the gold and silver color options from PearlsTreasuresArt and check the original listing for the selected finish.", "image_url": "https://i.etsystatic.com/46725934/r/il/cf8739/6773432570/il_794xN.6773432570_rpbv.jpg", "facebook_draft": "A coastal finishing touch from PearlsTreasuresArt: shell drop earrings with gold and silver color options. https://www.etsy.com/listing/1899462379/handmade-seashell-drop-earrings-boho", "checked_at": "2026-10-19T02:39:03.068980+00:00", "visual_verified": true, "available": true}, {"shop": "PearlsTreasuresArt", "handle": "cindyzhang62", "listing_id": "1867791265", "source_url": "https://www.etsy.com/listing/1867791265/conch-shell-stud-earrings-natural", "category": "Seashell Jewelry", "board_id": "675399344058025061", "new_title": "White Conch Shell Earrings", "body": "White spiral shells add an ocean-inspired detail to casual outfits or occasion styling. Explore these earrings from PearlsTreasuresArt and review the original listing for product details.", "image_url": "https://i.etsystatic.com/46725934/r/il/1cbd7a/6730472009/il_794xN.6730472009_b9fk.jpg", "facebook_draft": "White conch shell earrings from PearlsTreasuresArt bring a coastal detail to your jewelry collection. https://www.etsy.com/listing/1867791265/conch-shell-stud-earrings-natural", "checked_at": "2026-10-19T02:39:03.068982+00:00", "visual_verified": true, "available": true}, {"shop": "PearlsTreasuresArt", "handle": "cindyzhang62", "listing_id": "4320437541", "source_url": "https://www.etsy.com/listing/4320437541/natural-seashell-hoop-earrings-beach", "category": "Seashell Jewelry", "board_id": "675399344058025061", "new_title": "Iridescent Shell Hoop Earrings", "body": "Iridescent shell drops hang from oversized silver-tone hoops. These earrings from PearlsTreasuresArt add a coastal accent to vacation outfits and relaxed occasion styling. Shell shapes and colors can vary.", "image_url": "https://i.etsystatic.com/46725934/r/il/063e9a/6939760456/il_794xN.6939760456_com2.jpg", "facebook_draft": "Pair iridescent shell drops with silver-tone hoops for a coastal look. See the original PearlsTreasuresArt listing for details. https://www.etsy.com/listing/4320437541/natural-seashell-hoop-earrings-beach", "checked_at": "2026-10-19T02:39:03.068984+00:00", "visual_verified": true, "available": true}]$data$::jsonb) x(shop text,listing_id text,source_url text,category text,board_id text,new_title text,body text,image_url text,checked_at timestamptz,facebook_draft text,handle text);
do $$ begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard required'; end if;
 if exists(select 1 from batch_input where checked_at<now()-interval '24 hours' or checked_at>now()) then raise exception 'Verification expired'; end if;
 if (select count(*) from batch_input x join shops s on s.shop_name=x.shop and s.status='active' join shop_social_accounts m on m.shop_id=s.id and m.active and m.platform='pinterest' join social_accounts a on a.id=m.social_account_id and a.handle=x.handle and a.active and a.platform='pinterest' join pinterest_oauth_credentials cr on cr.social_account_id=a.id and lower(cr.pinterest_username)=x.handle)<>4 then raise exception 'Batch routing or authorization changed'; end if;
end $$;
-- Report prior records before inserting; only genuinely new products enter this batch.
select json_build_object('preexisting_listing',p.etsy_listing_id,'history_count',(select count(*) from publish_history h where h.product_id=p.id)) from products p join batch_input x on x.listing_id=p.etsy_listing_id;
create temporary table new_products(id uuid,shop_id uuid,etsy_listing_id text);
with ins as (
 insert into products(shop_id,etsy_listing_id,etsy_url,title,category,listing_status,primary_image_url,original_image_urls,source_payload,source_discovered_at,last_seen_at)
 select s.id,x.listing_id,x.source_url,x.new_title,x.category,'active',x.image_url,jsonb_build_array(x.image_url),jsonb_build_object('verified_at',x.checked_at,'source',x.source_url,'image_verified',true,'batch','daily-20261019-b13'),x.checked_at,x.checked_at from batch_input x join shops s on s.shop_name=x.shop
 where not exists(select 1 from products p where p.etsy_listing_id=x.listing_id)
 on conflict(shop_id,etsy_listing_id) do nothing returning id,shop_id,etsy_listing_id
) insert into new_products select * from ins;
insert into content_variants(shop_id,product_id,platform,creative_id,image_url,title,body,destination_url,board_or_category,content_type,status)
select p.shop_id,p.id,'pinterest','verified-original-20261019',x.image_url,x.new_title,x.body,x.source_url,x.category,'product','ready' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id;
insert into content_variants(shop_id,product_id,platform,creative_id,image_url,title,body,destination_url,board_or_category,content_type,status)
select p.shop_id,p.id,'facebook','verified-original-20261019',x.image_url,x.new_title,x.facebook_draft,x.source_url,x.category,'product','draft' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id;
insert into publish_queue(shop_id,product_id,content_variant_id,platform,social_account_id,status)
select p.shop_id,p.id,cv.id,'pinterest',a.id,'ready' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id join content_variants cv on cv.product_id=p.id and cv.platform='pinterest' join social_accounts a on a.handle=x.handle and a.platform='pinterest';
insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select q.id,x.board_id,pinterest_publish_snapshot(q.id),x.checked_at,x.source_url from new_products p join batch_input x on x.listing_id=p.etsy_listing_id join publish_queue q on q.product_id=p.id and q.platform='pinterest';
select json_build_object('listing_id',p.etsy_listing_id,'queue_id',q.id,'status',q.status,'board_id',r.board_id,'snapshot_matches',r.snapshot=pinterest_publish_snapshot(q.id)) from products p join batch_input x on x.listing_id=p.etsy_listing_id join publish_queue q on q.product_id=p.id and q.platform='pinterest' join pinterest_publish_reviews r on r.queue_id=q.id;
commit;
